export const SCHEMA_SQL = "-- Khan Baba platform schema (PostgreSQL / Supabase).\n--\n-- Applied automatically on the first query of every process (see lib/db/index.ts):\n-- every statement is idempotent, so this file doubles as the migration script.\n-- Types: identity integers for keys, timestamptz for instants, date for calendar\n-- days, boolean for flags, double precision for quantities and integer cents for\n-- money (never floats — the money math stays in whole cents).\n\nCREATE TABLE IF NOT EXISTS settings (\n  key TEXT PRIMARY KEY,\n  value TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS staff (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  email TEXT NOT NULL UNIQUE,\n  role TEXT NOT NULL CHECK (role IN ('admin','manager','counter','kitchen','delivery')),\n  password_hash TEXT NOT NULL,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS categories (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  slug TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  description TEXT,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  active BOOLEAN NOT NULL DEFAULT TRUE\n);\n\nCREATE TABLE IF NOT EXISTS menu_items (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  slug TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  tagline TEXT,\n  description TEXT,\n  category_id INTEGER REFERENCES categories(id),\n  image TEXT,\n  gallery TEXT,                       -- JSON array of image paths\n  youtube_id TEXT,                    -- plays inline via youtube-nocookie\n  ingredients TEXT,                   -- comma separated, customer facing\n  allergens TEXT,                     -- comma separated\n  spice_levels TEXT NOT NULL DEFAULT 'blend,mild,hot,extra_hot',\n  prep_minutes INTEGER NOT NULL DEFAULT 15,\n  is_veg BOOLEAN NOT NULL DEFAULT FALSE,\n  is_available BOOLEAN NOT NULL DEFAULT TRUE,\n  is_featured BOOLEAN NOT NULL DEFAULT FALSE,\n  is_new BOOLEAN NOT NULL DEFAULT FALSE,\n  published BOOLEAN NOT NULL DEFAULT TRUE,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS item_variants (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  item_id INTEGER NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE,\n  label TEXT NOT NULL,\n  size_ml INTEGER,\n  price_cents INTEGER NOT NULL,\n  is_default BOOLEAN NOT NULL DEFAULT FALSE,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_variants_item ON item_variants(item_id);\n\nCREATE TABLE IF NOT EXISTS reviews (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  item_id INTEGER NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE,\n  order_code TEXT,\n  customer_name TEXT NOT NULL,\n  rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),\n  comment TEXT,\n  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','published','hidden')),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_reviews_item ON reviews(item_id, status);\n\n-- Manufacturing / costing ---------------------------------------------------\nCREATE TABLE IF NOT EXISTS materials (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  sku TEXT UNIQUE,\n  unit TEXT NOT NULL DEFAULT 'kg',\n  pack_qty DOUBLE PRECISION NOT NULL DEFAULT 1,   -- how much one purchase pack contains (in `unit`)\n  pack_cost_cents INTEGER NOT NULL DEFAULT 0,\n  stock_qty DOUBLE PRECISION NOT NULL DEFAULT 0,  -- current stock in `unit`\n  reorder_level DOUBLE PRECISION NOT NULL DEFAULT 0,\n  supplier TEXT,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS recipes (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  output_kind TEXT NOT NULL DEFAULT 'batch' CHECK (output_kind IN ('menu_item','batch')),\n  menu_item_id INTEGER REFERENCES menu_items(id),\n  output_qty DOUBLE PRECISION NOT NULL DEFAULT 1,\n  output_unit TEXT NOT NULL DEFAULT 'portion',\n  prep_minutes INTEGER NOT NULL DEFAULT 30,\n  notes TEXT,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS recipe_lines (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  recipe_id INTEGER NOT NULL REFERENCES recipes(id) ON DELETE CASCADE,\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  qty DOUBLE PRECISION NOT NULL,\n  unit TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_recipe_lines ON recipe_lines(recipe_id);\n\nCREATE TABLE IF NOT EXISTS production_batches (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  ref TEXT NOT NULL UNIQUE,\n  recipe_id INTEGER NOT NULL REFERENCES recipes(id),\n  planned_qty DOUBLE PRECISION NOT NULL,\n  status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress','completed','cancelled')),\n  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  completed_at TIMESTAMPTZ,\n  created_by TEXT,\n  total_cost_cents INTEGER NOT NULL DEFAULT 0,\n  notes TEXT\n);\n\nCREATE TABLE IF NOT EXISTS cost_postings (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  batch_id INTEGER NOT NULL REFERENCES production_batches(id) ON DELETE CASCADE,\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  material_name TEXT NOT NULL,\n  qty DOUBLE PRECISION NOT NULL,\n  unit TEXT,\n  unit_cost_cents INTEGER NOT NULL,\n  amount_cents INTEGER NOT NULL,\n  posted_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_cost_postings_batch ON cost_postings(batch_id);\n\n-- Pricing -------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS pricing_rules (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  label TEXT NOT NULL,\n  kind TEXT NOT NULL CHECK (kind IN ('weekend','public_holiday','priority','peak')),\n  calc TEXT NOT NULL CHECK (calc IN ('percent','flat')),\n  value DOUBLE PRECISION NOT NULL,\n  applies_to TEXT NOT NULL DEFAULT 'all',      -- all | delivery,pickup | delivery | pickup | dine_in | table\n  days TEXT,                                   -- CSV 0=Sun..6=Sat, null = every day\n  start_time TEXT,                             -- HH:MM (Sydney)\n  end_time TEXT,\n  min_subtotal_cents INTEGER NOT NULL DEFAULT 0,\n  description TEXT,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS holidays (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  date DATE NOT NULL UNIQUE,                   -- read back as text YYYY-MM-DD\n  name TEXT NOT NULL,\n  surcharge_percent DOUBLE PRECISION,\n  active BOOLEAN NOT NULL DEFAULT TRUE\n);\n\nCREATE TABLE IF NOT EXISTS dining_tables (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  zone TEXT,\n  seats INTEGER NOT NULL DEFAULT 4,\n  active BOOLEAN NOT NULL DEFAULT TRUE\n);\n\n-- Customers -----------------------------------------------------------------\n-- An account is optional: browsing, table QR ordering and the tracking link all\n-- work signed out. These rows are what turn a one-off order into history —\n-- \"my orders\", saved delivery details, and a counter lookup that does not\n-- depend on the customer remembering an order code. Guests are rows with\n-- guest = TRUE and no password; they are upgraded in place at sign-up.\nCREATE TABLE IF NOT EXISTS customers (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  name TEXT NOT NULL,\n  email TEXT NOT NULL UNIQUE,                 -- stored lowercased\n  phone TEXT,\n  password_hash TEXT,                         -- null until a guest registers\n  address TEXT,\n  suburb TEXT,\n  postcode TEXT,\n  marketing_opt_in BOOLEAN NOT NULL DEFAULT FALSE,\n  guest BOOLEAN NOT NULL DEFAULT FALSE,\n  active BOOLEAN NOT NULL DEFAULT TRUE,\n  last_order_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_customers_email ON customers(lower(email));\n\nCREATE TABLE IF NOT EXISTS customer_activity (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL,                          -- signup | signin | order | orders_claimed | profile_updated\n  detail TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_customer_activity ON customer_activity(customer_id, created_at DESC);\n\n-- Orders --------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS orders (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  code TEXT NOT NULL UNIQUE,\n  customer_id INTEGER REFERENCES customers(id),\n  tracking_token TEXT UNIQUE,                 -- the sharable /t/<token> link\n  channel TEXT NOT NULL CHECK (channel IN ('delivery','pickup','dine_in','table')),\n  table_id INTEGER REFERENCES dining_tables(id),\n  customer_name TEXT NOT NULL,\n  phone TEXT,\n  email TEXT,\n  address TEXT,\n  suburb TEXT,\n  postcode TEXT,\n  notes TEXT,\n  subtotal_cents INTEGER NOT NULL DEFAULT 0,\n  surcharge_cents INTEGER NOT NULL DEFAULT 0,\n  surcharge_detail TEXT,\n  priority BOOLEAN NOT NULL DEFAULT FALSE,\n  priority_fee_cents INTEGER NOT NULL DEFAULT 0,\n  delivery_fee_cents INTEGER NOT NULL DEFAULT 0,\n  delivery_cost_cents INTEGER NOT NULL DEFAULT 0,\n  total_cents INTEGER NOT NULL DEFAULT 0,\n  payment_method TEXT NOT NULL CHECK (payment_method IN ('online','counter')),\n  payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid','pending','paid','refunded','failed')),\n  payment_ref TEXT,\n  status TEXT NOT NULL DEFAULT 'pending_confirm' CHECK (status IN ('pending_confirm','confirmed','preparing','ready','out_for_delivery','awaiting_collection','completed','cancelled')),\n  progress INTEGER NOT NULL DEFAULT 5,\n  promised_at TIMESTAMPTZ,\n  confirmed_at TIMESTAMPTZ,\n  kitchen_started_at TIMESTAMPTZ,\n  ready_at TIMESTAMPTZ,\n  dispatched_at TIMESTAMPTZ,\n  completed_at TIMESTAMPTZ,\n  cancelled_reason TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n-- Upgrades for databases created by an earlier release. CREATE TABLE IF NOT\n-- EXISTS skips a table that is already there, so a column added later never\n-- reaches an existing database on its own. Every column added to an existing\n-- table after its first release must also be listed here, above any index that\n-- uses it. ADD COLUMN IF NOT EXISTS is a no-op once the column exists.\nALTER TABLE orders ADD COLUMN IF NOT EXISTS customer_id INTEGER REFERENCES customers(id);\nALTER TABLE orders ADD COLUMN IF NOT EXISTS tracking_token TEXT UNIQUE;\n\nCREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_orders_channel ON orders(channel, created_at DESC);\n\nCREATE TABLE IF NOT EXISTS order_items (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  item_id INTEGER,\n  variant_id INTEGER,\n  name TEXT NOT NULL,\n  variant_label TEXT,\n  size_ml INTEGER,\n  spice_level TEXT,\n  qty INTEGER NOT NULL DEFAULT 1,\n  unit_price_cents INTEGER NOT NULL,\n  line_total_cents INTEGER NOT NULL,\n  notes TEXT,\n  prep_state TEXT NOT NULL DEFAULT 'queued' CHECK (prep_state IN ('queued','preparing','ready'))\n);\nCREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);\n\nCREATE TABLE IF NOT EXISTS order_events (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  type TEXT NOT NULL,\n  message TEXT NOT NULL,\n  actor TEXT,\n  progress INTEGER,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_order_events ON order_events(order_id, created_at);\n\n-- One-time links that let a guest prove they own an order and attach it to an\n-- account. Only the SHA-256 of the token is stored, so a database leak cannot be\n-- replayed as anyone's tracking link, and used_at makes each link single-use.\nCREATE TABLE IF NOT EXISTS order_claims (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  token_hash TEXT NOT NULL UNIQUE,\n  email TEXT NOT NULL,\n  used_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_order_claims_order ON order_claims(order_id);\n\nCREATE TABLE IF NOT EXISTS payments (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  provider TEXT NOT NULL,\n  intent_id TEXT,\n  amount_cents INTEGER NOT NULL,\n  status TEXT NOT NULL,\n  method TEXT,\n  last4 TEXT,\n  raw TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  paid_at TIMESTAMPTZ\n);\n\n-- Delivery ------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS delivery_jobs (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  provider TEXT NOT NULL,\n  provider_quote_id TEXT,\n  provider_delivery_id TEXT,\n  cost_cents INTEGER NOT NULL DEFAULT 0,\n  customer_fee_cents INTEGER NOT NULL DEFAULT 0,\n  markup_cents INTEGER NOT NULL DEFAULT 0,\n  status TEXT NOT NULL DEFAULT 'quoted' CHECK (status IN ('quoted','requested','accepted','pickup','dropoff','delivered','cancelled','failed')),\n  courier_name TEXT,\n  courier_phone TEXT,\n  tracking_url TEXT,\n  eta_minutes INTEGER,\n  quote_json TEXT,\n  external_status TEXT,\n  triggered_by TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  dispatched_at TIMESTAMPTZ,\n  completed_at TIMESTAMPTZ\n);\nCREATE INDEX IF NOT EXISTS idx_delivery_jobs_order ON delivery_jobs(order_id);\n\n-- What's new / release notes ------------------------------------------------\nCREATE TABLE IF NOT EXISTS whats_new (\n  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n  title TEXT NOT NULL,\n  summary TEXT NOT NULL,\n  body TEXT,\n  category TEXT NOT NULL DEFAULT 'feature' CHECK (category IN ('feature','improvement','fix','portal','ops')),\n  version TEXT,\n  pr_number INTEGER,\n  pr_url TEXT,\n  pinned BOOLEAN NOT NULL DEFAULT FALSE,\n  published_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n";
